import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
const here=import.meta.dirname,hash=s=>createHash('sha256').update(s).digest('hex'),read=n=>JSON.parse(fs.readFileSync(here+'/results/'+n));
const prices=[...read('sizes.json').observations,...read('solid-sizes.json').observations,...read('perf-sizes.json').observations,...read('perf-solid-sizes.json').observations];
if(prices.length!==1438)throw Error('Incomplete byte campaign '+prices.length);
const keys=new Set();for(const row of prices){const key=row.name+'/'+row.mode;if(keys.has(key))throw Error('Duplicate price '+key);keys.add(key);const file=here+`/.out/${row.mode==='solid'?'solid':'measured'}/${key}.js`,code=fs.readFileSync(file,'utf8').replace(/\/\/# sourceMappingURL=.*\n?$/,'');if(hash(code)!==row.sha256)throw Error('Price/output hash mismatch '+key);if(Buffer.byteLength(code)!==row.full.raw)throw Error('Raw byte mismatch '+key);if(Object.values(row.origins).reduce((a,b)=>a+b,0)!==row.full.raw)throw Error('Unaccounted raw bytes '+key);}
const validations=read('validation.json').observations;
if(validations.length!==1422||new Set(validations.map(x=>x.name+'/'+x.mode)).size!==1422)throw Error('Incomplete validation campaign');
let knownFailures=0;for(const row of validations){const bad=row.error||row.errors?.length||!row.matches_tea||row.identity_failures;if(bad){if(row.mode!=='direct'||!JSON.stringify(row).includes('undeclared template fallback'))throw Error('Unexpected validation failure '+row.name+'/'+row.mode);knownFailures++}if(row.sha256){const f=here+`/.out/${row.mode==='solid'?'solid':'measured'}/${row.name}/${row.mode}.js`;if(hash(fs.readFileSync(f))!==row.sha256)throw Error('Validated file changed')}}
const timed=read('timing.json').samples;if(timed.length!==828)throw Error('Incomplete timing campaign');
for(const row of timed){if(row.error)throw Error('Timing failure');const file=here+`/.out/${row.mode==='solid'?'solid':'measured'}/${row.name}/${row.mode}.js`;if(hash(fs.readFileSync(file))!==row.bundle_sha256)throw Error('Timed output changed');}
for(const row of read('lifetimes.json').observations)if(!row.unchanged||!row.detached||row.error||row.errors.length)throw Error('Lifetime failure');
const perf=read('perf-validation.json').observations;if(perf.length!==16)throw Error('Incomplete large-list validation');for(const row of perf)if(!row.matches_tea||row.identity_failures||row.errors.length||row.error)throw Error('Large-list validation failure');
const files=[];function walk(root){for(const e of fs.readdirSync(root,{withFileTypes:true})){if(['node_modules','out','.out','.git'].includes(e.name))continue;const file=path.join(root,e.name);if(e.isDirectory())walk(file);else if(e.name!=='manifest.json')files.push({path:path.relative(here,file),bytes:fs.statSync(file).size,sha256:hash(fs.readFileSync(file))})}}walk(here);
fs.writeFileSync(here+'/results/manifest.json',JSON.stringify({created:new Date().toISOString(),node:process.version,byte_observations:prices.length,validated_pages:validations.length,known_direct_failures:knownFailures,large_list_validations:perf.length,timed_clicks:timed.length,lifetime_probes:read('lifetimes.json').observations.length,files:files.sort((a,b)=>a.path.localeCompare(b.path))},null,2)+'\n');console.log('Verified prices, attribution, validation/timing bundle hashes and campaign completeness');
